mapper.select:
        select
        noticeComments.*,
        notice.banner_img,
        notice.title,
        users.nick_name,
        users.head_img,
        users1.nick_name as nickNameTwo,
        users1.head_img as headImgTwo
        from notice_comments noticeComments
        left join notice notice on noticeComments.notice_id = notice.id
		left join users users on noticeComments.user_id = users.id
		left join users users1 on noticeComments.to_user_id = users1.id

            and noticeComments.id = #{id}
            and noticeComments.comment_info like concat('%',#{commentInfo},'%')
            and noticeComments.user_id = #{userId}
            and noticeComments.notice_id = #{noticeId}
            and noticeComments.create_time = #{createTime}
            and noticeComments.to_user_id = #{toUserId}
            and noticeComments.parent_id = #{parentId}
            and notice.banner_img = #{bannerImg}
            and notice.title like concat('%',#{title},'%')
            and users.nick_name like concat('%',#{nickName},'%')
            and users.head_img = #{headImg}


            limit #{current},#{pageSize}

        select count(*) from notice_comments noticeComments
        left join notice notice on noticeComments.notice_id = notice.id
		left join users users on noticeComments.user_id = users.id
        left join users users1 on noticeComments.to_user_id = users1.id

            and noticeComments.id = #{id}
            and noticeComments.comment_info like concat('%',#{commentInfo},'%')
            and noticeComments.user_id = #{userId}
            and noticeComments.notice_id = #{noticeId}
            and noticeComments.create_time = #{createTime}
            and noticeComments.to_user_id = #{toUserId}
            and noticeComments.parent_id = #{parentId}
            and notice.banner_img = #{bannerImg}
            and notice.title like concat('%',#{title},'%')
            and users.nick_name like concat('%',#{nickName},'%')
            and users.head_img = #{headImg}
